fn gcd_i(mut m: i32, mut n: i32) -> i32 {
    // Both m and n must be strictly positive
    assert!(m > 0 && n > 0, "Inputs must be greater than zero");

    // Subtraction-based Euclidean algorithm
    while m != n {
        if m > n {
            m -= n;
        } else {
            n -= m;
        }
    }

    // When they are equal, that's the GCD
    m
}